[DllImport("iphlpapi.dll")] static extern uint GetExtendedTcpTable(IntPtr table, ref uint size, [MarshalAs(UnmanagedType.Bool)] bool order, uint family, uint tableClass, uint reserved);
[StructLayout(LayoutKind.Sequential)] struct Tcp4Row {
    public uint state, localAddress, localPort, remoteAddress, remotePort, owner;
}
[StructLayout(LayoutKind.Sequential)] struct Tcp6Row {
    [MarshalAs(UnmanagedType.ByValArray, SizeConst=16)] public byte[] localAddress;
    public uint localScope, localPort;
    [MarshalAs(UnmanagedType.ByValArray, SizeConst=16)] public byte[] remoteAddress;
    public uint remoteScope, remotePort, state, owner;
}
[StructLayout(LayoutKind.Sequential)] struct Tcp4Table { public uint count; public Tcp4Row first; }
[StructLayout(LayoutKind.Sequential)] struct Tcp6Table { public uint count; public Tcp6Row first; }
public static int[] ListenerOwners(int port) {
    if(port<1 || port>65535) throw new ArgumentOutOfRangeException("port");
    List<int> owners=new List<int>(); Stopwatch clock=Stopwatch.StartNew();
    // OWNER_PID_LISTENER (3) includes wildcard and duplicate listeners.
    // Marshal derives both table alignment and row stride from the SDK fields.
    foreach(uint family in new uint[] { 2, 23 }) {
        bool ipv4=family==2; Type row=ipv4?typeof(Tcp4Row):typeof(Tcp6Row);
        int stride=Marshal.SizeOf(row);
        int header=Marshal.OffsetOf(ipv4?typeof(Tcp4Table):typeof(Tcp6Table),"first").ToInt32();
        int portOffset=Marshal.OffsetOf(row,"localPort").ToInt32();
        int stateOffset=Marshal.OffsetOf(row,"state").ToInt32();
        int ownerOffset=Marshal.OffsetOf(row,"owner").ToInt32();
        if(header!=4 || stride!=(ipv4?24:56) || portOffset!=(ipv4?8:20) ||
            stateOffset!=(ipv4?0:48) || ownerOffset!=(ipv4?20:52))
            throw new InvalidOperationException("Unexpected native TCP listener layout.");
        uint size=0; uint error=GetExtendedTcpTable(IntPtr.Zero,ref size,false,family,3,0);
        if(error!=122) throw new InvalidOperationException("TCP listener size query failed: "+error);
        bool complete=false;
        for(int attempt=0;attempt<3 && clock.ElapsedMilliseconds<500;attempt++) {
            if(size<(uint)header || size>1048576) throw new InvalidOperationException("TCP listener table exceeds its bounded buffer.");
            uint capacity=size; IntPtr buffer=Marshal.AllocHGlobal(checked((int)capacity));
            try {
                uint used=capacity; error=GetExtendedTcpTable(buffer,ref used,false,family,3,0);
                if(error==122) { size=used; continue; }
                if(error!=0) throw new Win32Exception(checked((int)error));
                if(used<(uint)header || used>capacity) throw new InvalidOperationException("TCP listener table returned an invalid length.");
                int count=Marshal.ReadInt32(buffer,0);
                if(count<0 || (long)header+(long)count*stride>used) throw new InvalidOperationException("TCP listener table returned an incomplete row set.");
                for(int index=0;index<count;index++) {
                    int offset=checked(header+index*stride);
                    if(Marshal.ReadInt32(buffer,offset+stateOffset)!=2) throw new InvalidOperationException("TCP listener table contains a non-listener.");
                    int localPort=(Marshal.ReadByte(buffer,offset+portOffset)<<8)|Marshal.ReadByte(buffer,offset+portOffset+1);
                    if(localPort!=port) continue;
                    int owner=Marshal.ReadInt32(buffer,offset+ownerOffset);
                    if(owner<=0) throw new InvalidOperationException("TCP listener has an invalid owner PID.");
                    owners.Add(owner);
                }
                complete=true; break;
            } finally { Marshal.FreeHGlobal(buffer); }
        }
        if(!complete || clock.ElapsedMilliseconds>=500) throw new InvalidOperationException("TCP listeners did not produce a complete bounded snapshot.");
    }
    return owners.ToArray();
}
static System.Threading.Timer deadline;
